<?php
namespace App\Reports\Standard;
use App\Reports\Queries\VendorLedgerReportQuery;use App\Services\Reports\Contracts\StandardReport;use App\Services\Reports\ReportResult;
final class VendorStatementReport extends AbstractStandardReport implements StandardReport{
 public function __construct(private readonly VendorLedgerReportQuery $ledger){}public function code():string{return 'VENDOR_STATEMENT';}public function parameters():array{return array_merge($this->periodParameters(),['vendor_id'=>$this->lookupParameter('Vendor','vendors')]);}
 public function run(array $p):ReportResult{if(empty($p['vendor_id']))return new ReportResult('Vendor Statement',[$this->col('posting_at','Date','datetime'),$this->col('document_number','Document'),$this->col('debit','Debit','money'),$this->col('credit','Credit','money'),$this->col('running_balance','Balance','money')],[],notes:['Pilih Vendor untuk membuka statement.']);$opening=$this->ledger->opening($p);$running=$opening;$rows=[];$debit=$credit=0.0;foreach($this->ledger->period($p)->orderBy('l.posting_at')->orderBy('l.id')->get() as $row){$debit+=(float)$row->debit;$credit+=(float)$row->credit;$running+=(float)$row->credit-(float)$row->debit;$row->running_balance=$running;$rows[]=$row;if(count($rows)>=(int)config('reports.screen_row_limit',5000))break;}return new ReportResult('Vendor Statement',[$this->col('posting_at','Date','datetime'),$this->col('document_number','Document'),$this->col('document_type','Type'),$this->col('business_unit','Business Unit'),$this->col('description','Description'),$this->col('debit','Debit','money'),$this->col('credit','Credit','money'),$this->col('running_balance','Balance','money')],$rows,['Opening Balance'=>$opening,'Closing Balance'=>$running],['debit'=>$debit,'credit'=>$credit,'running_balance'=>$running],metadata:['opening_balance'=>$opening,'closing_balance'=>$running]);}
}
